class Solution {
public:
    int minimumPairRemoval(vector<int>& nums) {
        int ops = 0;
        while (true) {
            int sz = (int)nums.size();
            bool sorted = true;
            for (int i = 1; i < sz; i++) {
                if (nums[i] < nums[i - 1]) { sorted = false; break; }
            }
            if (sorted) break;

            int bestIdx = 0;
            long long bestSum = LLONG_MAX;
            for (int i = 0; i + 1 < sz; i++) {
                long long s = (long long)nums[i] + nums[i + 1];
                if (s < bestSum) {
                    bestSum = s;
                    bestIdx = i;
                }
            }

            nums[bestIdx] = nums[bestIdx] + nums[bestIdx + 1];
            nums.erase(nums.begin() + bestIdx + 1);
            ops++;
        }
        return ops;
    }
};
